"""Card capture and refunds.

Charge failures in some code paths are documented as failing closed with HTTP
500. Restoring warehouse stock after a refund is inventory's job, not this
module's ledger.
"""

_CHARGES: list[dict] = []


def charge(user_id: int, amount: float, items: list[dict]) -> dict:
    rec = {
        "user_id": user_id,
        "amount": amount,
        "items": items,
        "status": "captured",
    }
    _CHARGES.append(rec)
    return rec


def refund(order: dict) -> dict:
    """Mark a capture as refunded. Does not touch warehouse stock."""
    return {"refunded": True, "amount": order.get("total", 0)}


def fail_closed_message() -> str:
    """Red herring for searches about crashes / HTTP 500."""
    return "charge failures should fail closed with HTTP 500"


def reset_store() -> None:
    _CHARGES.clear()

"""Quotes, tax, and coupons.

A coupon code should change the payable amount at most once. Checkout currently
does not call ``compute_checkout_total``.
"""

COUPONS = {
    "SAVE10": 0.10,
    "SAVE20": 0.20,
}


def quote_price(sku: str, qty: int, unit_price: float) -> float:
    """Unit quote helper; not used by ``orders.create_order``."""
    return round(unit_price * qty, 2)


def apply_tax(subtotal: float, tax_rate: float = 0.0) -> float:
    return round(subtotal * (1 + tax_rate), 2)


def apply_coupon(amount: float, code: str | None) -> float:
    if not code:
        return round(float(amount), 2)
    rate = COUPONS.get(code.upper(), 0.0)
    return round(float(amount) * (1.0 - rate), 2)


def compute_checkout_total(
    items: list[dict],
    coupon: str | None = None,
    tax_rate: float = 0.0,
) -> float:
    """One-shot subtotal → coupon → tax. Unused by the order service today."""
    subtotal = sum(float(item["price"]) * int(item.get("qty", 1)) for item in items)
    discounted = apply_coupon(subtotal, coupon)
    return apply_tax(discounted, tax_rate)

"""Warehouse stock and bin allocation."""

from fastapi import HTTPException

_DEFAULT_STOCK: dict[str, int] = {
    "widget": 3,
    "gadget": 10,
}

_STOCK: dict[str, int] = dict(_DEFAULT_STOCK)

WAREHOUSE_BINS = {
    "widget": {"aisle": "A1", "slots": [0, 1, 2]},
    "gadget": {"aisle": "B2", "slots": list(range(10))},
}


def get_stock(sku: str) -> int:
    return int(_STOCK.get(sku, 0))


def reserve(sku: str, qty: int) -> None:
    """Take ``qty`` units of ``sku`` or raise HTTP 409."""
    available = get_stock(sku)
    if qty > available:
        raise HTTPException(status_code=409, detail="out of stock")
    _STOCK[sku] = available - qty


def release(sku: str, qty: int) -> None:
    _STOCK[sku] = get_stock(sku) + qty


def allocate_bin(items: list[dict]) -> str:
    """Pick a warehouse aisle for the line items and decrement stock."""
    last_aisle = "A1"
    for item in items:
        sku = item.get("sku") or "widget"
        qty = int(item.get("qty", 1))
        bins = WAREHOUSE_BINS[sku]
        last_aisle = bins["aisle"]
        _ = bins["slots"][qty - 1]
        _STOCK[sku] = get_stock(sku) - qty
    return last_aisle


def reset_store() -> None:
    """Test helper — restore seeded stock."""
    _STOCK.clear()
    _STOCK.update(_DEFAULT_STOCK)

